using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

public static class TestHelper
{
    public static SchoolContext CreateContext(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        return new SchoolContext(options);
    }

    public static SchoolContext CreateSeededContext(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var context = CreateContext(dbName);
        SeedData(context);
        return context;
    }

    public static void SeedData(SchoolContext context)
    {
        var instructor1 = new Instructor
        {
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Parse("1995-03-11")
        };
        var instructor2 = new Instructor
        {
            FirstMidName = "Fadi",
            LastName = "Fakhouri",
            HireDate = DateTime.Parse("2002-07-06")
        };
        context.Instructors.AddRange(instructor1, instructor2);
        context.SaveChanges();

        var dept1 = new Department
        {
            Name = "English",
            Budget = 350000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = instructor1.ID
        };
        var dept2 = new Department
        {
            Name = "Mathematics",
            Budget = 100000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = instructor2.ID
        };
        context.Departments.AddRange(dept1, dept2);
        context.SaveChanges();

        var course1 = new Course
        {
            CourseID = 2021,
            Title = "Composition",
            Credits = 3,
            DepartmentID = dept1.DepartmentID
        };
        var course2 = new Course
        {
            CourseID = 1045,
            Title = "Calculus",
            Credits = 4,
            DepartmentID = dept2.DepartmentID
        };
        context.Courses.AddRange(course1, course2);
        context.SaveChanges();

        var student1 = new Student
        {
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = DateTime.Parse("2010-09-01")
        };
        var student2 = new Student
        {
            FirstMidName = "Meredith",
            LastName = "Alonso",
            EnrollmentDate = DateTime.Parse("2012-09-01")
        };
        var student3 = new Student
        {
            FirstMidName = "Arturo",
            LastName = "Anand",
            EnrollmentDate = DateTime.Parse("2013-09-01")
        };
        context.Students.AddRange(student1, student2, student3);
        context.SaveChanges();

        context.Enrollments.AddRange(
            new Enrollment { StudentID = student1.ID, CourseID = course1.CourseID, Grade = Grade.A },
            new Enrollment { StudentID = student2.ID, CourseID = course2.CourseID, Grade = Grade.B }
        );
        context.SaveChanges();

        // CourseAssignment
        context.CourseAssignments.Add(new CourseAssignment
        {
            CourseID = course1.CourseID,
            InstructorID = instructor1.ID
        });
        context.SaveChanges();

        // OfficeAssignment
        context.OfficeAssignments.Add(new OfficeAssignment
        {
            InstructorID = instructor2.ID,
            Location = "Smith 17"
        });
        context.SaveChanges();
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut = new();

    public void Dispose() => _sut.Dispose();

    // Drain the static queue between tests to avoid cross-test pollution
    private static void DrainQueue()
    {
        using var drain = new NotificationService();
        while (drain.ReceiveNotification() != null) { }
    }

    [Fact]
    public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
    {
        DrainQueue();

        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("Student 'John Doe'", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        DrainQueue();

        _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Course (ID: 101)", notification.Message);
        Assert.Contains("updated", notification.Message);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_AllOperations_GenerateCorrectVerb(EntityOperation op, string expectedVerb)
    {
        DrainQueue();

        _sut.SendNotification("Entity", "1", "Test", op, "User");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains(expectedVerb, notification.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        DrainQueue();

        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void SendAndReceive_FifoOrder()
    {
        DrainQueue();

        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();

        Assert.NotNull(first);
        Assert.NotNull(second);
        Assert.Equal("A", first.EntityType);
        Assert.Equal("B", second.EntityType);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        DrainQueue();

        _sut.SendNotification("Dept", "5", "Math", EntityOperation.CREATE, null);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation — just verify no exception
        var exception = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(exception);
    }
}

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_FirstPage_ContainsCorrectItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.First());
        Assert.Equal(10, result.Last());
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void Create_MiddlePage_HasBothNavigationFlags()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
        Assert.Equal(11, result.First());
        Assert.Equal(20, result.Last());
    }

    [Fact]
    public void Create_LastPage_HasNoPreviousPageFlagCorrectAndNoNextPage()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.True(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
        Assert.Equal(5, result.Count);
        Assert.Equal(21, result.First());
    }

    [Fact]
    public void Create_FirstPage_HasNoPreviousPage()
    {
        var source = Enumerable.Range(1, 5).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
        Assert.Equal(1, result.TotalPages);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
    }

    [Theory]
    [InlineData(10, 10, 1)]
    [InlineData(11, 10, 2)]
    [InlineData(20, 10, 2)]
    [InlineData(1, 10, 1)]
    public void Create_VariousCounts_CalculatesTotalPagesCorrectly(int itemCount, int pageSize, int expectedPages)
    {
        var source = Enumerable.Range(1, itemCount).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: pageSize);

        Assert.Equal(expectedPages, result.TotalPages);
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestHelper.CreateSeededContext();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudents()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Index_WithSearchString_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_NameDescSort_SortsDescending()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.True(model.Count > 1);
        Assert.True(string.Compare(model[0].LastName, model[1].LastName) > 0);
    }

    [Fact]
    public void Index_DateSort_SortsByEnrollmentDateAscending()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.True(model.Count > 1);
        Assert.True(model[0].EnrollmentDate <= model[1].EnrollmentDate);
    }

    [Fact]
    public void Index_DateDescSort_SortsByEnrollmentDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.True(model.Count > 1);
        Assert.True(model[0].EnrollmentDate >= model[1].EnrollmentDate);
    }

    [Fact]
    public void Index_NewSearch_ResetsToPage1()
    {
        var result = _controller.Index(null, null, "A", 5) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        var result = _controller.Index(null, "Alexander", null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var studentId = _context.Students.First().ID;

        var result = _controller.Details(studentId) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(studentId, model.ID);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        var result = _controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Contains(_context.Students, s => s.LastName == "Student");
    }

    [Fact]
    public void Create_Post_InvalidDate_ReturnsViewWithError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_DateOutOfRange_ReturnsViewWithError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(1752, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        var studentId = _context.Students.First().ID;

        var result = _controller.Edit(studentId) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(studentId, model.ID);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
