using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestHelper.CreateSeededContext();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_NoParams_ReturnsViewWithAllInstructors()
    {
        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var instructorId = _context.Instructors.First().ID;

        var result = _controller.Index(instructorId, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
    }

    [Fact]
    public void Index_WithInstructorAndCourseId_PopulatesEnrollments()
    {
        var instructor = _context.Instructors.First();
        var courseAssignment = _context.CourseAssignments.First(ca => ca.InstructorID == instructor.ID);

        var result = _controller.Index(instructor.ID, courseAssignment.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Enrollments);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        var instructorId = _context.Instructors.First().ID;

        var result = _controller.Details(instructorId) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructorId, model.ID);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Details_NonexistentId_ReturnsNotFound()
    {
        var result = _controller.Details(99999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithInstructor()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.Empty(model.CourseAssignments);
    }

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Instructor",
            HireDate = DateTime.Parse("2023-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Contains(_context.Instructors, i => i.LastName == "Instructor");
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AssignsCourses()
    {
        var courseId = _context.Courses.First().CourseID;
        var instructor = new Instructor
        {
            FirstMidName = "Course",
            LastName = "Assigned",
            HireDate = DateTime.Parse("2023-01-01")
        };
        var selectedCourses = new[] { courseId.ToString() };

        var result = _controller.Create(instructor, selectedCourses) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .First(i => i.LastName == "Assigned");
        Assert.Single(saved.CourseAssignments);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        var instructorId = _context.Instructors.First().ID;

        var result = _controller.Edit(instructorId) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsView()
    {
        var instructorId = _context.Instructors.First().ID;

        var result = _controller.Delete(instructorId) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructorId, model.ID);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_NonexistentId_ReturnsNotFound()
    {
        var result = _controller.Delete(99999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_RemovesInstructorAndRedirects()
    {
        // Use instructor without department administrator reference to avoid FK conflicts
        var instructor = _context.Instructors.First(i =>
            !_context.Departments.Any(d => d.InstructorID == i.ID));

        var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsDeptAdmin_NullsOutDepartmentAdmin()
    {
        var dept = _context.Departments.First(d => d.InstructorID != null);
        var instructorId = dept.InstructorID!.Value;

        _controller.DeleteConfirmed(instructorId);

        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.Null(updatedDept!.InstructorID);
    }
