using ContosoUniversity.Data;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_EmptyDatabase_SeedsAllData()
    {
        using var context = TestHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.True(context.Students.Any());
        Assert.True(context.Instructors.Any());
        Assert.True(context.Departments.Any());
        Assert.True(context.Courses.Any());
        Assert.True(context.Enrollments.Any());
        Assert.True(context.CourseAssignments.Any());
        Assert.True(context.OfficeAssignments.Any());
    }

    [Fact]
    public void Initialize_AlreadySeeded_DoesNotDuplicateData()
    {
        using var context = TestHelper.CreateContext();
        DbInitializer.Initialize(context);
        var studentCountBefore = context.Students.Count();

        DbInitializer.Initialize(context);
        var studentCountAfter = context.Students.Count();

        Assert.Equal(studentCountBefore, studentCountAfter);
    }

    [Fact]
    public void Initialize_SeedsExpectedStudentCount()
    {
        using var context = TestHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.Students.Count());
    }

    [Fact]
    public void Initialize_SeedsExpectedInstructorCount()
    {
        using var context = TestHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(5, context.Instructors.Count());
    }

    [Fact]
    public void Initialize_SeedsExpectedDepartmentCount()
    {
        using var context = TestHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(4, context.Departments.Count());
    }

    [Fact]
    public void Initialize_SeedsExpectedCourseCount()
    {
        using var context = TestHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(7, context.Courses.Count());
    }

    [Fact]
    public void Initialize_DepartmentsHaveInstructorAdministrators()
    {
        using var context = TestHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.All(context.Departments.ToList(), d => Assert.NotNull(d.InstructorID));
    }

    [Fact]
    public void Initialize_CoursesAreAssignedToDepartments()
    {
        using var context = TestHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.All(context.Courses.ToList(), c => Assert.True(c.DepartmentID > 0));
    }

    [Fact]
    public void Initialize_EnrollmentsHaveValidStudentAndCourseIds()
    {
        using var context = TestHelper.CreateContext();

        DbInitializer.Initialize(context);

        var studentIds = context.Students.Select(s => s.ID).ToHashSet();
        var courseIds = context.Courses.Select(c => c.CourseID).ToHashSet();

        Assert.All(context.Enrollments.ToList(), e =>
        {
            Assert.Contains(e.StudentID, studentIds);
            Assert.Contains(e.CourseID, courseIds);
        });
    }
}

