using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models;

public class ModelTests
{
    [Theory]
    [InlineData("Smith", "John", "Smith, John")]
    [InlineData("Doe", "Jane", "Doe, Jane")]
    [InlineData("O'Brien", "Alice", "O'Brien, Alice")]
    public void Person_FullName_ReturnsConcatenatedLastAndFirst(string lastName, string firstName, string expected)
    {
        var student = new Student { LastName = lastName, FirstMidName = firstName };

        Assert.Equal(expected, student.FullName);
    }

    [Fact]
    public void ErrorViewModel_ShowRequestId_TrueWhenSet()
    {
        var model = new ErrorViewModel { RequestId = "abc123" };

        Assert.True(model.ShowRequestId);
    }

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    public void ErrorViewModel_ShowRequestId_FalseWhenNullOrEmpty(string? requestId)
    {
        var model = new ErrorViewModel { RequestId = requestId! };

        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void Student_InheritsFromPerson()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = DateTime.Parse("2023-01-01")
        };

        Assert.IsAssignableFrom<Person>(student);
        Assert.Equal("User, Test", student.FullName);
    }

    [Fact]
    public void Instructor_InheritsFromPerson()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "Prof",
            HireDate = DateTime.Parse("2023-01-01")
        };

        Assert.IsAssignableFrom<Person>(instructor);
        Assert.Equal("Prof, Test", instructor.FullName);
    }

    [Fact]
    public void Notification_PropertiesSetCorrectly()
    {
        var now = DateTime.Now;
        var notification = new Notification
        {
            Id = 1,
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "Test message",
            CreatedAt = now,
            CreatedBy = "Admin",
            IsRead = false,
            ReadAt = null
        };

        Assert.Equal(1, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("Test message", notification.Message);
        Assert.Equal(now, notification.CreatedAt);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Null(notification.ReadAt);
    }

    [Theory]
    [InlineData(Grade.A)]
    [InlineData(Grade.B)]
    [InlineData(Grade.C)]
    [InlineData(Grade.D)]
    [InlineData(Grade.F)]
    public void Enrollment_Grade_AcceptsAllValues(Grade grade)
    {
        var enrollment = new Enrollment { Grade = grade };

        Assert.Equal(grade, enrollment.Grade);
    }

    [Fact]
    public void Enrollment_Grade_NullableAllowsNull()
    {
        var enrollment = new Enrollment { Grade = null };

        Assert.Null(enrollment.Grade);
    }
}

