using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void Context_CanAddAndRetrieveStudent()
    {
        using var context = TestHelper.CreateContext();
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.First(s => s.LastName == "Student");
        Assert.Equal("Test", retrieved.FirstMidName);
    }

    [Fact]
    public void Context_CanAddAndRetrieveInstructor()
    {
        using var context = TestHelper.CreateContext();
        var instructor = new Instructor
        {
            FirstMidName = "Prof",
            LastName = "Test",
            HireDate = DateTime.Parse("2020-01-01")
        };

        context.Instructors.Add(instructor);
        context.SaveChanges();

        var retrieved = context.Instructors.First(i => i.LastName == "Test");
        Assert.Equal("Prof", retrieved.FirstMidName);
    }

    [Fact]
    public void Context_CourseAssignment_HasCompositeKey()
    {
        using var context = TestHelper.CreateContext();
        var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now };
        context.Instructors.Add(instructor);
        var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course { CourseID = 5555, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        var retrieved = context.CourseAssignments.Find(course.CourseID, instructor.ID);
        Assert.NotNull(retrieved);
    }

    [Fact]
    public void Context_InstructorOfficeAssignment_OneToOne()
    {
        using var context = TestHelper.CreateContext();
        var instructor = new Instructor
        {
            FirstMidName = "Office",
            LastName = "Test",
            HireDate = DateTime.Now,
            OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
        };

        context.Instructors.Add(instructor);
        context.SaveChanges();

        var retrieved = context.Instructors
            .Include(i => i.OfficeAssignment)
            .First(i => i.LastName == "Test");

        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void Context_Enrollment_LinksCourseAndStudent()
    {
        using var context = TestHelper.CreateContext();
        var student = new Student { FirstMidName = "S", LastName = "T", EnrollmentDate = DateTime.Now };
        context.Students.Add(student);
        var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course { CourseID = 7777, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var retrieved = context.Enrollments
            .Include(e => e.Student)
            .Include(e => e.Course)
            .First(e => e.StudentID == student.ID);

        Assert.Equal("T", retrieved.Student.LastName);
        Assert.Equal("C", retrieved.Course.Title);
        Assert.Equal(Grade.A, retrieved.Grade);
    }

    [Fact]
    public void Context_AllDbSetsAreAccessible()
    {
        using var context = TestHelper.CreateContext();

        Assert.NotNull(context.Courses);
        Assert.NotNull(context.Enrollments);
        Assert.NotNull(context.Departments);
        Assert.NotNull(context.OfficeAssignments);
        Assert.NotNull(context.CourseAssignments);
        Assert.NotNull(context.People);
        Assert.NotNull(context.Students);
        Assert.NotNull(context.Instructors);
        Assert.NotNull(context.Notifications);
    }
}

